      "arFull": "هٰۤؤُلَآءِ قَوْمُنَا اتَّخَذُوْا مِنْ دُوْنِهٖۤ اٰلِهَةً ؕ لَوْلَا یَاْتُوْنَ عَلَیْهِمْ بِسُلْطٰنٍ بَیِّنٍ ؕ فَمَنْ اَظْلَمُ مِمَّنِ افْتَرٰی عَلَی اللّٰهِ كَذِبًا ۟ؕ",
