      "arFull": "وَاَمَّا الْغُلٰمُ فَكَانَ اَبَوٰهُ مُؤْمِنَیْنِ فَخَشِیْنَاۤ اَنْ یُّرْهِقَهُمَا طُغْیَانًا وَّكُفْرًا ۟ۚ",
