      "arFull": "لَّذِیْنَ كَانَتْ اَعْیُنُهُمْ فِیْ غِطَآءٍ عَنْ ذِكْرِیْ وَكَانُوْا لَا یَسْتَطِیْعُوْنَ سَمْعًا ۟۠",
