      "arFull": "اَفَحَسِبَ الَّذِیْنَ كَفَرُوْۤا اَنْ یَّتَّخِذُوْا عِبَادِیْ مِنْ دُوْنِیْۤ اَوْلِیَآءَ ؕ اِنَّاۤ اَعْتَدْنَا جَهَنَّمَ لِلْكٰفِرِیْنَ نُزُلًا ۟",
      "ur": "کیا کافر یہ خیال کیے بیٹھے ہیں؟ کہ میرے سوا وه میرے بندوں کو اپنا حمایتی بنا لیں گے؟ (سنو) ہم نے تو ان کفار کی مہمانی کے لئے جہنم کو تیار کر رکھا ہے.[1]",
