      "arFull": "اُولٰٓىِٕكَ الَّذِیْنَ كَفَرُوْا بِاٰیٰتِ رَبِّهِمْ وَلِقَآىِٕهٖ فَحَبِطَتْ اَعْمَالُهُمْ فَلَا نُقِیْمُ لَهُمْ یَوْمَ الْقِیٰمَةِ وَزْنًا ۟",
